3. const flipDecimals = 18;
4. const usdcDecimals = 6;
5. 
6. const getPositiveDifference = (assetDecimals: number) => Math.max(0, flipDecimals - assetDecimals);
7. const getNegativeDifference = (assetDecimals: number) => Math.max(0, assetDecimals - flipDecimals);
8. 
9. const increaseScale = (value: number | string, difference: number): BigNumber => {
10.   if (difference === 0) {
11.     return BigNumber.from(value);
12.   }
13. 
14.   const originalValue = BigNumber.from(value);
15.   return originalValue.mul(10 ** Math.abs(difference));
16. };
17. 
18. const decreaseScale = (value: number | string, difference: number): BigNumber => {
19.   if (difference === 0) {
20.     return BigNumber.from(value);
21.   }
22. 
23.   const originalValue = BigNumber.from(value);
24.   return originalValue.div(10 ** Math.abs(difference));
25. };
