27. /**
28.  * Converts a value from the asset's decimal scale to the FLIP decimal scale (18 decimals).
29.  * The FLIP scale is used for Chainflip deposits to ensure consistent precision across assets.
30.  */
31. export const scaleToFlipDecimals = (amount: string | number, assetDecimals: number): BigNumber => {
32.   const positiveDifference = getPositiveDifference(assetDecimals);
33.   const negativeDifference = getNegativeDifference(assetDecimals);
34. 
35.   if (positiveDifference > 0) {
36.     return increaseScale(amount, positiveDifference);
37.   }
38. 
39.   if (negativeDifference > 0) {
40.     return decreaseScale(amount, negativeDifference);
41.   }
42. 
43.   return BigNumber.from(amount);
44. };
45. 
46. export const scaleUsdToUsdcDecimals = (amount: string | number): BigNumber => {
47.   if (amount === 0 || amount === '0') {
48.     return BigNumber.from(0);
49.   }
50. 
51.   return BigNumber.from(amount).mul(10 ** usdcDecimals);
52. };
53. 
54. /**
55.  * Converts a value from the FLIP decimal scale (18 decimals) to the asset's decimal scale.
56.  * Used for converting DCA minimum chunk sizes from FLIP precision to asset precision.
57.  */
58. export const scaleFromFlipDecimals = (amount: string | number, assetDecimals: number): BigNumber => {
59.   const positiveDifference = getPositiveDifference(assetDecimals);
60.   const negativeDifference = getNegativeDifference(assetDecimals);
61. 
62.   if (positiveDifference > 0) {
63.     return decreaseScale(amount, positiveDifference);
64.   }
65. 
66.   if (negativeDifference > 0) {
67.     return increaseScale(amount, negativeDifference);
68.   }
69. 
70.   return BigNumber.from(amount);
71. };
72. 
73. export const scaleUsdcToUsdDecimals = (amount: string | number): BigNumber => {
74.   return BigNumber.from(amount).div(10 ** usdcDecimals);
75. };
