import {
  ChainflipNetwork,
  chains,
  executeSwap,
  getInternalAsset,
  type ChainflipChain,
  type ChainflipAsset,
  type ChainflipNetworkOptions,
} from '@chainflip-io/sdk/swap';
import { assert } from '@chainflip-io/utils/assertion';

import { PRIVATE_KEY, RPC_NODE_HTTP_URL } from '../config';

type SwapArgs = {
  srcAsset: string;
  destChain: string;
  destAsset: string;
  destAddress: string;
  amount: string;
  ccmMessage?: string;
  ccmGasBudget?: string;
  brokerCommissionBps?: string;
  boostFee?: string;
};

const chainIdToEthNetwork: Partial<Record<ChainflipNetwork, 'mainnet' | 'goerli'>> = {
  mainnet: 'mainnet',
  perseverance: 'goerli',
};

const isChainflipNetwork = (network: string): network is ChainflipNetwork =>
  Object.values(ChainflipNetwork).includes(network as ChainflipNetwork);

const executeSwapCommand = () => async (args: SwapArgs) => {
  const {
    srcAsset,
    destChain,
    destAsset,
    destAddress,
    amount,
    ccmMessage,
    ccmGasBudget,
    brokerCommissionBps,
    boostFee,
  } = args;

  if (!isChainflipNetwork(RPC_NODE_HTTP_URL.NETWORK)) throw new Error('Invalid network');
  const chainflipNetwork = RPC_NODE_HTTP_URL.NETWORK;
  const ethNetwork = chainIdToEthNetwork[chainflipNetwork];
  assert(ethNetwork !== undefined, 'Invalid network');

  const ccmMetadata =
    ccmMessage && ccmGasBudget
      ? {
          message: ccmMessage,
          gasBudget: ccmGasBudget,
        }
      : undefined;

  const chainflipNetworkOptions: ChainflipNetworkOptions = {
    network: chainflipNetwork,
    broker: brokerCommissionBps,
  };

  const signer = new Wallet(
    PRIVATE_KEY,
    RPC_NODE_HTTP_URL.ETHEREUM
      ? getDefaultProvider(RPC_NODE_HTTP_URL.ETHEREUM)
      : new providers.AlchemyProvider(ethNetwork, process.env.ALCHEMY_KEY),
  );

  await executeSwap(
    {
      srcAsset: getInternalAsset(srcAsset, undefined) as ChainflipAsset,
      destChain: destChain as ChainflipChain,
      destAsset: getInternalAsset(destAsset, destChain as ChainflipChain) as ChainflipAsset,
      destAddress,
      amount,
      ccmParams: ccmMetadata,
      boostFee: boostFee ? Number(boostFee) : undefined,
    },
    {
      ...chainflipNetworkOptions,
      signer,
    },
  );
};

export default executeSwapCommand;

