     7	import { ERC20, ERC20__factory } from './abis';
     8	import { ADDRESSES, GOERLI_USDC_CONTRACT_ADDRESS } from './consts';
     9	import {
    10	  type ChainflipNetwork,
    11	  type Asset,
    12	  Assets,
