    14	} from './enums';
    15	import { assert } from './guards';
    16	
    17	export type TransactionOptions = {
    18	  gasLimit?: bigint;
    19	  gasPrice?: bigint;
    20	  maxFeePerGas?: bigint;
    21	  maxPriorityFeePerGas?: bigint;
    22	  nonce?: bigint;
    23	  wait?: number;
    24	};
    25	
    26	export const extractOverrides = (
    27	  transactionOverrides: TransactionOptions,
    28	): ethers.Overrides => {
    29	  const { wait, ...ethersOverrides } = transactionOverrides;
    30	
    31	  return ethersOverrides;
    32	};
    33	
    34	export const getTokenContractAddress = (
    35	  asset: Asset,
    36	  network: ChainflipNetwork,
    37	): string => {
    38	  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');
    39	
    40	  if (asset === Assets.FLIP) return ADDRESSES[network].FLIP_CONTRACT_ADDRESS;
    41	
    42	  assert(asset === Assets.USDC, 'Only FLIP and USDC are supported for now');
    43	
    44	  return GOERLI_USDC_CONTRACT_ADDRESS;
    45	};
    46	
    47	export const getStateChainGatewayContractAddress = (
    48	  network: ChainflipNetwork,
    49	): string => {
    50	  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');
    51	  return ADDRESSES[network].STATE_CHAIN_GATEWAY_ADDRESS;
    52	};
    53	
    54	export const checkAllowance = async (
    55	  amount: BigNumberish,
    56	  spenderAddress: string,
    57	  erc20Address: string,
    58	  signer: Signer,
    59	) => {
    60	  const erc20 = ERC20__factory.connect(erc20Address, signer);
    61	  const signerAddress = await signer.getAddress();
    62	  const allowance = await erc20.allowance(signerAddress, spenderAddress);
    63	  return { allowance, isAllowable: allowance.gte(amount), erc20 };
    64	};
    65	
    66	export const approve = async (
    67	  amount: BigNumberish,
    68	  spenderAddress: string,
    69	  erc20: ERC20,
    70	  allowance: BigNumberish,
    71	  txOpts: TransactionOptions,
    72	): Promise<ContractReceipt | null> => {
    73	  const amountBigNumber = BigNumber.from(amount);
    74	  const allowanceBigNumber = BigNumber.from(allowance);
    75	  if (allowanceBigNumber.gte(amountBigNumber)) return null;
    76	  const requiredAmount = amountBigNumber.sub(allowanceBigNumber);
    77	  const transaction = await erc20.approve(
    78	    spenderAddress,
    79	    requiredAmount,
    80	    extractOverrides(txOpts),
    81	  );
    82	  return transaction.wait(txOpts.wait);
    83	};
    84	
    85	export const getVaultManagerContractAddress = (
    86	  network: ChainflipNetwork,
    87	): string => {
    88	  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');
    89	  return ADDRESSES[network].VAULT_CONTRACT_ADDRESS;
    90	};
