export type TransactionOptions = {
  gasLimit?: bigint;
  gasPrice?: bigint;
  maxFeePerGas?: bigint;
  maxPriorityFeePerGas?: bigint;
  nonce?: bigint;
  wait?: number;
};

export type ContractReceipt = TransactionReceipt & { transactionHash: string };

export const extractOverrides = (
  transactionOverrides: TransactionOptions,
): Overrides => {
  const { wait, ...ethersOverrides } = transactionOverrides;

  return ethersOverrides;
};

export const waitForTransactionReceipt = async (
  transaction: ContractTransactionResponse,
  confirmations?: number,
): Promise<ContractReceipt> => {
  const receipt = await transaction.wait(confirmations);
  if (!receipt) throw new Error('Transaction was not mined');
  return Object.assign(receipt, { transactionHash: receipt.hash });
};

const toBigIntAmount = (
  value: BigNumberish | { toString(): string; toBigInt?: () => bigint },
) =>
  typeof value === 'object' && 'toBigInt' in value && value.toBigInt
    ? value.toBigInt()
    : toBigInt(value as BigNumberish);

export const getTokenContractAddress = (
  asset: Asset,
  network: ChainflipNetwork,
): string => {
  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');

  if (asset === Assets.FLIP) return ADDRESSES[network].FLIP_CONTRACT_ADDRESS;

  assert(asset === Assets.USDC, 'Only FLIP and USDC are supported for now');

  return GOERLI_USDC_CONTRACT_ADDRESS;
};

export const getStateChainGatewayContractAddress = (
  network: ChainflipNetwork,
): string => {
  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');
  return ADDRESSES[network].STATE_CHAIN_GATEWAY_ADDRESS;
};

export const checkAllowance = async (
  amount: BigNumberish,
  spenderAddress: string,
  erc20Address: string,
  signer: Signer,
) => {
  const erc20 = ERC20__factory.connect(erc20Address, signer);
  const signerAddress = await signer.getAddress();
  const allowance = await erc20.allowance(signerAddress, spenderAddress);
  return {
    allowance,
    isAllowable: toBigIntAmount(allowance) >= toBigIntAmount(amount),
    erc20,
  };
};

export const approve = async (
  amount: BigNumberish,
  spenderAddress: string,
  erc20: ERC20,
  allowance: BigNumberish,
  txOpts: TransactionOptions,
): Promise<ContractReceipt | null> => {
  const amountBigInt = toBigIntAmount(amount);
  const allowanceBigInt = toBigIntAmount(allowance);
  if (allowanceBigInt >= amountBigInt) return null;
  const requiredAmount = amountBigInt - allowanceBigInt;
  const transaction = await erc20.approve(
    spenderAddress,
    requiredAmount,
    extractOverrides(txOpts),
  );
  return waitForTransactionReceipt(transaction, txOpts.wait);
};

export const getVaultManagerContractAddress = (
  network: ChainflipNetwork,
): string => {
  assert(network !== ChainflipNetworks.mainnet, 'Mainnet is not yet supported');
  return ADDRESSES[network].VAULT_CONTRACT_ADDRESS;
};

export const getFlipBalance = async (
  network: ChainflipNetwork,
  signer: Signer,
): Promise<bigint> => {
  const flipAddress = getTokenContractAddress('FLIP', network);
  const flip = ERC20__factory.connect(flipAddress, signer);
  const balance = await flip.balanceOf(await signer.getAddress());
  return toBigIntAmount(balance);
};

